def legend_position_settings(position, below_anchor=(1.0, -0.20)):
    """Converts a GUI legend choice into Matplotlib visibility and location settings."""

    if position == "Hidden":
        return False, False, {}

    if position == "Below":
        return (
            True,
            True,
            {
                "loc": "upper right",
                "bbox_to_anchor": below_anchor,
            },
        )

    return (
        True,
        False,
        {
            "loc": LEGEND_POSITION_LOCATIONS.get(
                position,
                "best",
            )
        },
    )

def ensure_packages():
    """Checks required packages and installs missing or incompatible versions."""

    # Each import is tested before the GUI starts so errors occur in one clear place.
    install_requests = []

    for module_name, pip_name in REQUIRED_PACKAGES.items():
        try:
            module = importlib.import_module(module_name)

            if (
                module_name == "sklearn"
                and module.__version__ != MODEL_SKLEARN_VERSION
            ):

                install_requests.append(pip_name)

        except ImportError:
            install_requests.append(pip_name)

    if install_requests:
        print(
            "Installing or adjusting packages:",
            ", ".join(install_requests),
        )
        subprocess.check_call(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                *install_requests,
            ]
        )
        print("Installation completed.")

ensure_packages()

