# ---------------------------------------------------------------------
# 2. Embedded model loading
#    Decode the original trained model without accessing the filesystem.
# ---------------------------------------------------------------------
def load_pls_model():
    """Loads the embedded Joblib bytes and validates their integrity and fields."""

    model_bytes = base64.b64decode(EMBEDDED_MODEL_BASE64)
    if hashlib.sha256(model_bytes).hexdigest() != EMBEDDED_MODEL_SHA256:
        raise ValueError("The embedded model data are damaged.")
    package = joblib.load(io.BytesIO(model_bytes))

    required_keys = {
        "x_axis_cm-1",
        "pls1_models",
        "model_status",
    }
    missing_keys = sorted(required_keys - set(package))

    if missing_keys:
        raise ValueError(
            "The selected PLS model is incomplete. Missing entries: "
            + ", ".join(missing_keys)
        )

    return package


def save_figure_high_quality(figure, output_path):
    """Saves a plot as high-resolution PNG or resolution-independent SVG."""

    output_path = Path(output_path)
    suffix = output_path.suffix.lower()
    legends = [
        legend
        for axis in figure.axes
        for legend in [axis.get_legend()]
        if legend is not None
    ]

    save_kwargs = {
        "bbox_inches": "tight",
        "facecolor": "white",
    }

    if legends:
        save_kwargs["bbox_extra_artists"] = tuple(legends)

    if suffix != ".svg":
        save_kwargs["dpi"] = PNG_EXPORT_DPI

    if suffix == ".png":
        save_kwargs["pil_kwargs"] = {
            "compress_level": 1,
        }

    figure.savefig(
        output_path,
        **save_kwargs,
    )


# ---------------------------------------------------------------------
# 3. UV-Vis calibration and concentration calculation
#    Reads the embedded Excel calibration and converts absorbance to NADH.
# ---------------------------------------------------------------------
def load_uv_vis_calibration():
    """Fits the unchanged calibration data embedded in this script."""

    calibration_sheet = pd.read_excel(
        io.BytesIO(base64.b64decode(EMBEDDED_UV_CALIBRATION_BASE64)),
        sheet_name=0,
        header=None,
    )

    concentration_row = pd.to_numeric(
        calibration_sheet.iloc[4],
        errors="coerce",
    )

    calibration_columns = concentration_row[
        concentration_row.notna()
    ].index

    concentrations = (
        concentration_row
        .loc[calibration_columns]
        .astype(float)
        .to_numpy()
    )

    absorbance_measurements = (
        calibration_sheet
        .iloc[5:14, calibration_columns]
        .apply(pd.to_numeric, errors="coerce")
    )

    mean_absorbance = (
        absorbance_measurements
        .mean(axis=0)
        .to_numpy(dtype=float)
    )

    valid = (
        np.isfinite(concentrations)
        & np.isfinite(mean_absorbance)
    )

    if valid.sum() < 2:
        raise ValueError(
            "The UV-Vis calibration needs at least two valid "
            "concentration/absorbance pairs."
        )

    slope, intercept = np.polyfit(
        mean_absorbance[valid],
        concentrations[valid],
        1,
    )

    predicted = (
        slope
        * mean_absorbance[valid]
        + intercept
    )

    ss_residual = np.sum(
        (
            concentrations[valid]
            - predicted
        ) ** 2
    )

    ss_total = np.sum(
        (
            concentrations[valid]
            - np.mean(concentrations[valid])
        ) ** 2
    )

    r_squared = (
        1.0 - ss_residual / ss_total
        if ss_total > 0
        else np.nan
    )

    return {
        "source": "Embedded UV-Vis calibration",
        "slope": float(slope),
        "intercept": float(intercept),
        "r_squared": float(r_squared),
        "concentrations": concentrations[valid],
        "mean_absorbance": mean_absorbance[valid],
    }


def read_uv_vis_csv(path):
    """Reads one UV-Vis CSV and identifies the time and absorbance columns."""

    attempts = [
        {
            "sep": ",",
            "decimal": ".",
        },
        {
            "sep": ";",
            "decimal": ",",
        },
        {
            "sep": "\t",
            "decimal": ".",
        },
        {
            "sep": "\t",
            "decimal": ",",
        },
    ]

    encodings = [
        "utf-8-sig",
        "cp1252",
        "latin1",
    ]

    for encoding in encodings:

        for kwargs in attempts:

            try:
                csv_data = pd.read_csv(
                    path,
                    header=None,
                    encoding=encoding,
                    engine="python",
                    on_bad_lines="skip",
                    **kwargs,
                )

                if csv_data.shape[1] < 2:
                    continue

                header_index = None

                for row_index, row in csv_data.iterrows():
                    first_cell = str(
                        row.iloc[0]
                    ).lower()

                    second_cell = str(
                        row.iloc[1]
                    ).lower()

                    if (
                        "time" in first_cell
                        and "abs" in second_cell
                    ):
                        header_index = row_index
                        break

                if header_index is None:
                    candidate = csv_data.iloc[:, :2].copy()
                else:
                    candidate = (
                        csv_data
                        .iloc[header_index + 1:, :2]
                        .copy()
                    )

                candidate.columns = [
                    "Time_min",
                    "Absorbance",
                ]

                candidate = (
                    candidate
                    .apply(pd.to_numeric, errors="coerce")
                    .dropna()
                    .reset_index(drop=True)
                )

                if not candidate.empty:
                    return candidate

            except Exception:
                pass

    raise ValueError(
            "The NADH CSV file could not be read. "
        "Expected columns are Time (min) and Abs."
    )


def calculate_uv_vis_concentrations(path, calibration):
    """Converts UV-Vis absorbance values into NADH concentrations."""

    uv_vis_data = read_uv_vis_csv(path)

    concentrations = (
        calibration["slope"]
        * uv_vis_data["Absorbance"]
        + calibration["intercept"]
    )

    low, high = np.min(calibration['concentrations']), np.max(calibration['concentrations'])
    valid = np.isfinite(concentrations) & concentrations.between(low, high)
    uv_vis_data['NADH_raw_mmol_L'] = concentrations
    uv_vis_data['Outside_calibration_range'] = ~valid
    uv_vis_data["NADH_concentration_mmol_L"] = concentrations.where(valid)

    return uv_vis_data


# ---------------------------------------------------------------------
# 4. Raman CSV input
#    Reads two-column Raman files and normalizes separator/decimal variants.
# ---------------------------------------------------------------------
def read_spectrum(path):
    """Reads one Raman CSV and returns cleaned Raman shift and intensity arrays."""

    # Different separators and decimal symbols are tried because exports vary.
    attempts = [
        {"sep": ";", "decimal": ","},
        {"sep": ",", "decimal": "."},
        {"sep": "\t", "decimal": ","},
        {"sep": "\t", "decimal": "."},
    ]

    for kwargs in attempts:
        try:
            df = pd.read_csv(path, header=None, **kwargs)

            if df.shape[1] >= 2:
                df = df.iloc[:, :2].copy()
                df.columns = ["shift", "intensity"]

                # Header text and invalid cells become missing values and are removed.
                df = df.apply(pd.to_numeric, errors="coerce").dropna()

                if len(df) > 100:
                    return (
                        df.sort_values("shift")
                        .drop_duplicates("shift")
                        .reset_index(drop=True)
                    )
        except Exception:
            pass

    raise ValueError(
        f"CSV file could not be read:\n{Path(path).name}"
    )


# ---------------------------------------------------------------------
# 5. Spectral preprocessing
#    Applies despiking, smoothing, baseline correction, derivatives, and SNV.
# ---------------------------------------------------------------------
def despike(y, kernel=5, threshold=8.0):
    """Replaces isolated spikes detected against a local median and robust MAD."""

    # The median filter estimates the local signal without following narrow spikes.
    median = medfilt(y, kernel_size=kernel)
    residual = y - median
    mad = np.median(
        np.abs(residual - np.median(residual))
    ) + 1e-12

    # Values farther than eight robust standard deviations are classified as spikes.
    bad = np.abs(residual) > threshold * 1.4826 * mad

    result = y.copy()
    # Only detected positions are replaced; all other measured intensities remain.
    result[bad] = median[bad]

    return result


def preprocess(y, mode, x_axis):
    """Applies the legacy preprocessing mode stored in older model packages."""

    # Step 1: Remove isolated detector or cosmic-ray spikes.
    cleaned = despike(y)

    # Step 2: Reduce high-frequency noise while preserving broad Raman bands.
    smooth = savgol_filter(
        cleaned,
        window_length=15,
        polyorder=3,
    )

    # Step 3: Estimate the slowly changing fluorescence background.
    baseline = savgol_filter(
        smooth,
        window_length=301,
        polyorder=2,
    )

    # Step 4: Subtract the background from the smoothed spectrum.
    corrected = smooth - baseline

    if mode == "bc":
        return corrected

    if mode == "snv":
        return (
            (corrected - corrected.mean())
            / (corrected.std(ddof=1) + 1e-12)
        )

    # Derivative modes emphasize changes in peak shape and reduce baseline effects.
    delta = float(np.median(np.diff(x_axis)))

    derivative = savgol_filter(
        cleaned,
        window_length=21,
        polyorder=3,
        deriv=1,
        delta=delta,
    )

    if mode == "d1":
        return derivative

    if mode == "d1snv":
        return (
            (derivative - derivative.mean())
            / (derivative.std(ddof=1) + 1e-12)
        )

    raise ValueError(
        f"Unknown preprocessing mode: {mode}"
    )


def preprocess_with_config(y, config, x_axis):
    """Reproduces the exact despiking, smoothing, baseline and scaling of training."""

    # New model packages store their optimized filter settings with each analyte.
    params = config.get("preprocess_params")

    if not params:
        return preprocess(
            y,
            config["preprocessing"],
            x_axis,
        )

    mode = params.get(
        "mode",
        config.get("preprocessing"),
    )

    cleaned = despike(y)

    if mode in (
        "bc",
        "snv",
    ):

        smooth = savgol_filter(
            cleaned,
            window_length=int(
                params.get(
                    "smooth_window",
                    15,
                )
            ),
            polyorder=int(
                params.get(
                    "smooth_poly",
                    3,
                )
            ),
        )

        baseline = savgol_filter(
            smooth,
            window_length=int(
                params.get(
                    "baseline_window",
                    301,
                )
            ),
            polyorder=int(
                params.get(
                    "baseline_poly",
                    2,
                )
            ),
        )

        corrected = smooth - baseline

        if mode == "bc":
            return corrected

        return (
            (corrected - corrected.mean())
            / (corrected.std(ddof=1) + 1e-12)
        )

    if mode in (
        "d1",
        "d1snv",
    ):

        delta = float(np.median(np.diff(x_axis)))

        derivative = savgol_filter(
            cleaned,
            window_length=int(
                params.get(
                    "derivative_window",
                    21,
                )
                or 21
            ),
            polyorder=int(
                params.get(
                    "derivative_poly",
                    3,
                )
                or 3
            ),
            deriv=1,
            delta=delta,
        )

        if mode == "d1":
            return derivative

        return (
            (derivative - derivative.mean())
            / (derivative.std(ddof=1) + 1e-12)
        )

    raise ValueError(
        f"Unknown preprocessing mode: {mode}"
    )


# ---------------------------------------------------------------------
# 6. CSV discovery and sample grouping
#    Builds sample groups for repeated measurements from file names.
# ---------------------------------------------------------------------
def sample_key(filename):
    """
    Examples:
    V1_1.CSV   -> V1
    V1_2.CSV   -> V1
    Probe-3.csv -> Probe
    Probe (4).csv -> Probe

    Repeated measurements of the same sample are grouped automatically.
    """

    stem = Path(filename).stem

    patterns = [
        r"^(.*?)[_-](\d+)$",
        r"^(.*?)\s*\((\d+)\)$",
    ]

    for pattern in patterns:
        match = re.match(pattern, stem)
        if match:
            return match.group(1)

    return stem


def natural_sort_key(path):
    """Sorts filenames by their embedded numbers instead of alphabetically."""

    return [
        int(part)
        if part.isdigit()
        else part.lower()
        for part in re.split(
            r"(\d+)",
            Path(path).stem,
        )
    ]


def group_csv_files(folder):
    """Groups all Raman CSV files by sample while preserving natural order."""

    csvs = list_csv_files(folder)

    if not csvs:
        raise ValueError(
            "No CSV files were found in the selected folder."
        )

    grouped = {}

    for path in csvs:
        key = sample_key(path.name)
        grouped.setdefault(key, []).append(path)

    # If no repetition numbers are recognizable, treat all CSV files
    # as one sample.
    if len(grouped) == len(csvs) and len(csvs) > 1:
        return {
            folder.name: csvs
        }

    return grouped


def list_csv_files(folder):
    """Returns naturally sorted CSV files for a time-resolved single run."""

    return sorted(
        (
            p for p in folder.iterdir()
            if p.is_file()
            and not p.name.startswith(".")
            and not p.name.startswith("~$")
            and p.suffix.lower() == ".csv"
        ),
        key=natural_sort_key,
    )


# ---------------------------------------------------------------------
# 7. Spectrum loading and averaging
#    Interpolates each CSV onto the model axis and averages repetitions.
# ---------------------------------------------------------------------
def load_mean_spectrum(files, x_model):
    """Interpolates all files to the model axis and returns mean plus individual spectra."""

    raw = []

    # Step 1: Read every technical replicate separately.
    for file in files:
        df = read_spectrum(file)

        x = df["shift"].to_numpy()
        y = df["intensity"].to_numpy()

        # Step 2: Interpolate onto the exact Raman axis used during training.
        raw.append(
            np.interp(
                x_model,
                x,
                y,
            )
        )

    # Step 3: Keep all individual spectra and calculate their display mean.
    matrix = np.vstack(raw)

    return matrix.mean(axis=0), matrix


# ---------------------------------------------------------------------
# 8. PLS1 concentration prediction
#    Runs the analyte-specific PLS1 models and range checks.
# ---------------------------------------------------------------------
def predict_sample(package, mean_raw):
    """Preprocesses one spectrum and predicts all analytes with the stored PLS1 models."""

    # Step 1: Use the exact Raman axis stored during model training.
    x_model = np.asarray(
        package["x_axis_cm-1"],
        dtype=float,
    )

    # -------------------------
    # PLS1
    # -------------------------
    pls1_result = {}

    # Step 2: Run one analyte-specific model for every target substance.
    for analyte, config in package["pls1_models"].items():

        # Step 3: Reproduce the optimized preprocessing stored with this model.
        transformed = preprocess_with_config(
            mean_raw,
            config,
            x_model,
        )

        # Step 4: Keep only the Raman ranges selected during training.
        mask = np.asarray(
            config["mask"],
            dtype=bool,
        )

        # Step 5: Convert the selected spectral variables into concentration.
        raw_prediction = float(
            config["model"]
            .predict(
                transformed[mask].reshape(1, -1)
            )
            .reshape(-1)[0]
        )

        # Output filtering never changes training, raw predictions, or the time axis.
        low, high = config["calibration_range_mM"]
        valid = bool(np.isfinite(raw_prediction) and low <= raw_prediction <= high)
        output_prediction = raw_prediction if valid else np.nan

        pls1_result[analyte] = {
            "prediction_mM": output_prediction,
            "raw_prediction_mM": raw_prediction,
            "range_low": float(low),
            "range_high": float(high),
            "outside_range": not valid,
            "valid_count": int(valid),
            "excluded_count": int(not valid),
            "status": package["model_status"][analyte],
        }

    return pls1_result


def analyte_display_name(analyte):
    """Converts internal analyte names to the English labels shown in the GUI."""


    replacements = {
        "Cyclohexanon": "Cyclohexanone",
    }

    return replacements.get(
        analyte,
        analyte,
    )


def set_errorbar_visibility(errorbar, visible):
    """Shows or hides all lines belonging to one error-bar object."""


    data_line, cap_lines, bar_collections = errorbar.lines

    if data_line is not None:
        data_line.set_visible(visible)

    for artist in (
        *cap_lines,
        *bar_collections,
    ):
        artist.set_visible(visible)


def summarize_replicate_predictions(predictions, calibration_range=(0.0, np.inf)):
    """Mean/SD of in-range repeats; raw values remain available for audit."""

    # The replicate predictions are kept separate until this final aggregation.
    predictions = np.asarray(
        predictions,
        dtype=float,
    )

    if predictions.size == 0:
        raise ValueError(
            "At least one replicate prediction is required."
        )

    low, high = calibration_range
    valid = np.isfinite(predictions) & (predictions >= low) & (predictions <= high)
    accepted = predictions[valid]
    finite = predictions[np.isfinite(predictions)]
    raw_mean = float(finite.mean()) if finite.size else np.nan

    return {
        "prediction_mM": float(accepted.mean()) if accepted.size else np.nan,
        "raw_prediction_mM": raw_mean,
        "valid_count": int(accepted.size),
        "excluded_count": int(predictions.size - accepted.size),
        "standard_deviation_mM": (
            float(np.std(accepted, ddof=1))
            if accepted.size > 1
            else np.nan
        ),
    }


# ---------------------------------------------------------------------
# 9. Tkinter GUI application
#    Handles measurement setup, upload, tables, plots, and exports.
# ---------------------------------------------------------------------
def plateau_statistics(raman, uv_vis, intervals, uv_offset=0.0):
    """Summarizes original, finite concentrations; smoothing and display stride never enter."""
    series = []
    for analyte, data in raman.groupby("Analyte", sort=False):
        series.append(("Raman", str(analyte), "", data["Time_min"], data["Concentration_mmol_L"]))
    groups = uv_vis.groupby("Source_path", sort=False) if "Source_path" in uv_vis else [("NADH", uv_vis)]
    for source, data in groups:
        series.append(("UV-Vis", "NADH", str(source), data["Time_min"] + uv_offset,
                       data["NADH_concentration_mmol_L"]))
    rows = []
    for region in intervals:
        for method, analyte, source, times, values in series:
            times = pd.to_numeric(times, errors="coerce").to_numpy(dtype=float)
            values = pd.to_numeric(values, errors="coerce").to_numpy(dtype=float)
            mask = (np.isfinite(times) & np.isfinite(values)
                    & (times >= region["start"]) & (times <= region["end"]))
            selected = values[mask]
            rows.append({"Plateau": region["name"], "Start_min": region["start"],
                         "End_min": region["end"], "Method": method, "Analyte": analyte,
                         "Source_path": source, "N": len(selected),
                         "Mean_mmol_L": float(np.mean(selected)) if len(selected) else np.nan,
                         "SD_mmol_L": float(np.std(selected, ddof=1)) if len(selected) > 1 else np.nan})
    return pd.DataFrame(rows, columns=["Plateau", "Start_min", "End_min", "Method", "Analyte",
                                       "Source_path", "N", "Mean_mmol_L", "SD_mmol_L"])


class PlateauAnalysisPanel:
    """Manages editable intervals and draggable bounds without changing source results."""

    def __init__(self, window, figure, canvas, intervals, data_provider, kind="plateau"):
        self.window, self.figure, self.canvas = window, figure, canvas
        self.intervals, self.data_provider = intervals, data_provider
        self.kind = kind
        self.edit_enabled = True
        self.axis = None
        self.artists = []
        self.bounds = []
        self.drag = None
        self.results = pd.DataFrame()
        self.frame = ttk.LabelFrame(window, text="Days" if kind == "day" else "Plateau statistics - original concentrations", padding=5)
        self.frame.pack(side="bottom", fill="x")
        bar = ttk.Frame(self.frame)
        bar.pack(fill="x")
        self.choice = ttk.Combobox(bar, state="readonly", width=17)
        self.choice.pack(side="left", padx=3)
        self.choice.bind("<<ComboboxSelected>>", self.select)
        self.name = tk.StringVar()
        self.start = tk.StringVar()
        self.end = tk.StringVar()
        for text, variable, width in [("Name", self.name, 15), ("Start / min", self.start, 8), ("End / min", self.end, 8)]:
            ttk.Label(bar, text=text).pack(side="left", padx=3)
            entry = ttk.Entry(bar, textvariable=variable, width=width)
            entry.pack(side="left")
            entry.bind("<Return>", self.apply)
        commands = [("Add", self.add), ("Apply", self.apply), ("Delete", self.delete)]
        if kind != "day":
            commands.append(("Save CSV", self.save))
        for text, command in commands:
            ttk.Button(bar, text=text, command=command).pack(side="left", padx=3)
        self.visible = tk.BooleanVar(value=True)
        ttk.Checkbutton(self.frame, text="Show interval boundaries (also in saved plot)",
                        variable=self.visible, command=self.draw).pack(anchor="w")
        columns = ["Plateau", "Start / min", "End / min", "Analyte", "Source", "n", "Mean / mmol L-1", "SD / mmol L-1"]
        area = ttk.Frame(self.frame)
        if kind != "day":
            area.pack(fill="x")
        self.table = ttk.Treeview(area, columns=columns, show="headings", height=4)
        for column in columns:
            self.table.heading(column, text=column)
            self.table.column(column, width=120, minwidth=55, stretch=True)
        scroll = ttk.Scrollbar(area, orient="vertical", command=self.table.yview)
        self.table.configure(yscrollcommand=scroll.set)
        self.table.pack(side="left", fill="x", expand=True)
        scroll.pack(side="right", fill="y")
        self.refresh_choices()
        canvas.mpl_connect("button_press_event", self.press)
        canvas.mpl_connect("motion_notify_event", self.motion)
        canvas.mpl_connect("button_release_event", self.release)

    def index(self):
        i = self.choice.current()
        return i if 0 <= i < len(self.intervals) else None

    def refresh_choices(self, index=0):
        self.choice.configure(values=[r["name"] for r in self.intervals])
        if self.intervals:
            self.choice.current(min(index, len(self.intervals) - 1))
            self.select()
        else:
            self.choice.set("")
            for v in (self.name, self.start, self.end):
                v.set("")

    def select(self, event=None):
        i = self.index()
        if i is not None:
            r = self.intervals[i]
            self.name.set(r["name"])
            self.start.set(f'{r["start"]:.3f}')
            self.end.set(f'{r["end"]:.3f}')
        self.draw()

    def add(self):
        if self.axis is None:
            return
        lo, hi = self.axis.get_xlim()
        if self.kind == "day":
            if not self.intervals:
                self.intervals.append({"name": "Day 2", "start": max(0, lo) + (hi-lo)/3,
                                       "end": max(0, lo) + 2*(hi-lo)/3})
            self.refresh_choices(0)
            return
        number = 1
        names = {r["name"] for r in self.intervals}
        prefix = "Day " if self.kind == "day" else "E"
        while f"{prefix}{number}" in names:
            number += 1
        start = max(r["end"] for r in self.intervals) if self.intervals else max(0, lo)
        end = start + (hi-lo) * (0.33 if self.kind == "day" else 0.10)
        self.intervals.append({"name": f"{prefix}{number}", "start": start, "end": end})
        self.refresh_choices(len(self.intervals)-1)
        self.update_statistics()

    def apply(self, event=None):
        i = self.index()
        if i is None:
            return
        try:
            start, end = [float(v.get().replace(",", ".")) for v in (self.start, self.end)]
            name = self.name.get().strip()
            if not (np.isfinite(start) and np.isfinite(end) and start < end and name):
                raise ValueError
            if any(j != i and r["name"] == name for j, r in enumerate(self.intervals)):
                raise ValueError
        except ValueError:
            messagebox.showerror("Invalid interval", "Enter a unique name and finite start < end.", parent=self.window)
            return
        self.intervals[i].update(name=name, start=start, end=end)
        self.refresh_choices(i)
        self.update_statistics()

    def delete(self):
        i = self.index()
        if i is not None:
            self.intervals.pop(i)
            self.refresh_choices()
            self.draw()
            self.update_statistics()

    def attach(self, axis):
        self.axis, self.artists, self.bounds, self.drag = axis, [], [], None
        self.draw()
        self.update_statistics()

    def draw(self):
        limits = self.axis.get_xlim() if self.axis is not None else None
        for artist in self.artists:
            artist.remove()
        self.artists, self.bounds = [], []
        if self.kind == "day":
            if self.axis is not None and self.visible.get() and self.intervals:
                # Only the middle interval is entered; outer day labels are inferred.
                r = self.intervals[0]
                lo, hi = limits
                start, end = r["start"], r["end"]
                for side in ("start", "end"):
                    line = self.axis.axvline(r[side], color="black", linestyle="--", linewidth=1.2)
                    line.set_visible(max(0, lo) < r[side] < hi)
                    self.artists.append(line)
                    self.bounds.append((0, side, line))
                for name, a, b in [("Day 1", max(0, lo), min(start, hi)),
                                    ("Day 2", max(start, lo), min(end, hi)),
                                    ("Day 3", max(end, lo), hi)]:
                    if a < b:
                        self.artists.append(self.axis.text((a+b)/2, 1.02, name,
                            transform=self.axis.get_xaxis_transform(), ha="center", va="bottom",
                            fontsize=12, clip_on=False))
                self.axis.set_xlim(limits)
            self.canvas.draw_idle()
            return
        if self.axis is not None and self.visible.get():
            for i, r in enumerate(self.intervals):
                active = i == self.index()
                if self.kind != "day":
                    self.artists.append(self.axis.axvspan(r["start"], r["end"], facecolor="0.65", edgecolor="none", alpha=0.28))
                for side in ("start", "end"):
                    line = self.axis.axvline(r[side], color="black" if self.kind == "day" else "0.2" if active else "0.6", linestyle="--", linewidth=1.5 if active else 0.8)
                    # Invisible handles keep extraction edges draggable without plotted lines.
                    line.set_visible(self.kind == "day")
                    self.artists.append(line)
                    self.bounds.append((i, side, line))
                if self.kind != "day":
                    self.artists.extend(self.axis.plot([r["start"], r["start"], r["end"], r["end"]],
                        [-0.18, -0.20, -0.20, -0.18], transform=self.axis.get_xaxis_transform(),
                        color="0.35", linewidth=0.8, clip_on=False))
                self.artists.append(self.axis.text((r["start"]+r["end"])/2,
                    1.02 if self.kind == "day" else -0.215, r["name"],
                    transform=self.axis.get_xaxis_transform(), ha="center",
                    va="bottom" if self.kind == "day" else "top", fontsize=12, clip_on=False))
        if limits is not None:
            self.axis.set_xlim(limits)
        self.canvas.draw_idle()

    def press(self, event):
        toolbar = getattr(self.canvas, "toolbar", None)
        if not self.edit_enabled or self.axis is None or event.button != 1 or event.inaxes not in self.figure.axes or (toolbar and toolbar.mode):
            return
        hits = [(abs(event.x-self.axis.transData.transform((line.get_xdata()[0], 0))[0]), i, side)
                for i, side, line in self.bounds]
        if hits and min(hits)[0] <= 9:
            _, i, side = min(hits)
            self.choice.current(i)
            self.select()
            self.drag = (i, side)

    def motion(self, event):
        if self.drag is None or event.x is None:
            return
        i, side = self.drag
        x = self.axis.transData.inverted().transform((event.x, 0))[0]
        r = self.intervals[i]
        if not np.isfinite(x) or (side == "start" and x >= r["end"]) or (side == "end" and x <= r["start"]):
            return
        r[side] = float(x)
        self.start.set(f'{r["start"]:.3f}')
        self.end.set(f'{r["end"]:.3f}')
        self.draw()

    def release(self, event):
        if self.drag is not None:
            self.drag = None
            self.update_statistics()

    def update_statistics(self):
        if self.kind == "day":
            return
        try:
            raman, uv, offset = self.data_provider()
            self.results = plateau_statistics(raman, uv, self.intervals, offset)
        except ValueError:
            return
        self.table.delete(*self.table.get_children())
        for _, row in self.results.iterrows():
            fmt = lambda value: f"{value:.5g}" if np.isfinite(value) else ""
            self.table.insert("", "end", values=[row.Plateau, fmt(row.Start_min), fmt(row.End_min),
                row.Analyte, Path(row.Source_path).name if row.Source_path else row.Method,
                row.N, fmt(row.Mean_mmol_L), fmt(row.SD_mmol_L)])

    def save(self):
        self.update_statistics()
        if self.results.empty:
            return
        path = filedialog.asksaveasfilename(parent=self.window, initialfile="Plateau_statistics.csv",
            defaultextension=".csv", filetypes=[("CSV", "*.csv")])
        if path:
            self.results.to_csv(path, index=False, encoding="utf-8-sig")


class RamanPLSApp:

    def __init__(self):
        """Loads the model, initializes application state, and builds the GUI."""

        if DND_AVAILABLE:
            self.root = TkinterDnD.Tk()
        else:
            self.root = tk.Tk()

        self.root.title(
            "Raman PLS - Concentration Analysis"
        )

        self.root.geometry("1400x850")
        self.root.minsize(1050, 680)

        self.uv_vis_window = tk.Toplevel(self.root)
        self.uv_vis_window.title("UV-Vis - NADH Analysis")
        self.uv_vis_window.geometry("1400x850")
        self.uv_vis_window.minsize(900, 680)
        self.closed_analysis_windows = set()

        for window in (self.root, self.uv_vis_window):
            window.protocol(
                "WM_DELETE_WINDOW",
                lambda selected=window: self.close_analysis_window(selected),
            )
            menu = tk.Menu(window)
            windows_menu = tk.Menu(menu, tearoff=False)
            windows_menu.add_command(
                label="Raman analysis",
                command=lambda: self.show_analysis_window(self.root),
            )
            windows_menu.add_command(
                label="UV-Vis analysis",
                command=lambda: self.show_analysis_window(self.uv_vis_window),
            )
            menu.add_cascade(label="Windows", menu=windows_menu)
            window.configure(menu=menu)

        self.package = load_pls_model()

        self.x_model = np.asarray(
            self.package["x_axis_cm-1"],
            dtype=float,
        )

        self.current_folder = None
        self.current_results = None
        self.current_means = None
        self.current_measurement_mode = None
        self.current_measurement_interval_min = None
        self.concentration_lines = {}
        self.rolling_average_lines = {}
        self.standard_deviation_artists = {}
        self.analyte_visibility_vars = {}
        self.analyte_toggle_widgets = []
        self.uv_vis_calibration = None
        self.uv_vis_current_path = None
        self.uv_vis_current_paths = []
        self.uv_vis_current_results = None
        self.nadh_custom_title_var = tk.StringVar(value="")
        self.show_nadh_plot_title_var = tk.BooleanVar(value=True)
        self.show_uv_vis_curve_names_var = tk.BooleanVar(value=True)
        self.uv_vis_point_step_var = tk.StringVar(value="1")
        self.nadh_y_tick_interval_var = tk.StringVar(value="20")
        self.nadh_title_var = tk.StringVar(value=NAD_PLUS_LABEL)
        self.uv_vis_curve_name_vars = {}

        self.build_gui()

    def show_analysis_window(self, window):
        """Reopens an analysis window without discarding its loaded data."""
        self.closed_analysis_windows.discard(window)
        window.deiconify()
        window.lift()

    def close_analysis_window(self, window):
        """Keeps the other analysis running until both windows are closed."""
        self.closed_analysis_windows.add(window)
        window.withdraw()
        if len(self.closed_analysis_windows) == 2:
            self.root.destroy()


